use AISkillsHub\Core\Commercial\{Enterprise,Sponsors,Bundles};
$enterprise=new Enterprise($db,$core->migrator());$sponsors=new Sponsors($db,$core->migrator(),$core->get('public_catalog'));$bundles=new Bundles($db,$core->migrator(),$query);
wp_set_current_user($admin);$initial=Enterprise::snapshot();$cfg=['enabled'=>true,'translations'=>['en_US'=>['title'=>'QA privacy inquiries','description'=>'Synthetic privacy-test form only.']]];$enterprise->saveConfig($cfg,$initial['revision']);$email='phase13-privacy-'.$run.'@example.invalid';$input=['name'=>'Synthetic privacy requester','email'=>$email,'message'=>'Synthetic private body for confirmed erasure regression.'];$id=$enterprise->receive($input,'en_US',hash('sha256',$run.':privacy'));$enterprise->moderate($id,1,'reviewing','Internal note is not exported');
p13_case('enterprise_native_confirmed_privacy_export_and_controlled_erasure',function()use($enterprise,$email,$id,$input,$admin,$db){wp_set_current_user($admin);p13_assert(is_wp_error($enterprise->exportPrivacy($email))&&is_wp_error($enterprise->erasePrivacy($email)),'Even administrator requires matching confirmed native request');$request=wp_create_user_request($email,'export_personal_data');p13_assert(is_int($request)&&$request>0,'Native privacy export request created');p13_assert(is_wp_error($enterprise->exportPrivacy($email)),'Unconfirmed request still denied');wp_update_post(['ID'=>$request,'post_status'=>'request-confirmed']);$data=$enterprise->exportPrivacy($email);p13_assert(is_array($data)&&count($data['data'])===1&&$data['done'],'Only matching private inquiry exported');$encoded=wp_json_encode($data);p13_assert(str_contains($encoded,$input['message'])&&str_contains($encoded,$email),'Requester receives own stored content');p13_assert(!str_contains($encoded,'Internal note is not exported'),'Internal manager notes excluded');$before=(int)$db->value('SELECT COUNT(*) FROM '.$db->connection()->posts." WHERE post_type='aish_message'");$events=count($enterprise->history($id));$erase=wp_create_user_request($email,'remove_personal_data');wp_update_post(['ID'=>$erase,'post_status'=>'request-confirmed']);$r=$enterprise->erasePrivacy($email);p13_assert(is_array($r)&&$r['items_removed']&&$r['done'],'Confirmed native erasure processed');$row=$enterprise->detail($id);p13_assert($row['post_content']===''&&$row['meta']['_aish_sender_name']===''&&$row['meta']['_aish_sender_email']===''&&$row['meta']['_aish_message_notes']==='','Body and contact/current notes removed');p13_assert($row['meta']['_aish_message_state']==='archived'&&$row['meta']['_aish_enterprise_erased']==='1','Anonymized record stays archived');p13_assert((int)$db->value('SELECT COUNT(*) FROM '.$db->connection()->posts." WHERE post_type='aish_message'")===$before&&count($enterprise->history($id))===$events,'Record identity and non-PII audit history retained');p13_reject(fn()=>$enterprise->moderate($id,(int)$row['meta']['_aish_enterprise_revision'],'pending','Restore'),'Erased inquiry cannot be revived');$repeat=$enterprise->erasePrivacy($email);p13_assert(is_array($repeat)&&!$repeat['items_removed']&&$repeat['done'],'Repeat erasure safe and idempotent');});
p13_case('commercial_option_and_private_inbox_transactional_audit_rollback',function()use($enterprise,$sponsors,$bundles,$db,$admin,$input,$run){wp_set_current_user($admin);$inject=static fn(string$sql):string=>preg_match('/^INSERT\s+INTO\s+`?wp_aish_workflow_events`?\s/i',$sql)?'SELECT phase13_controlled_failure FROM no_such_phase13_qa_table':$sql;$s=$sponsors->snapshot();$e=Enterprise::snapshot();$b=$bundles->configuration();$count=(int)$db->value('SELECT COUNT(*) FROM '.$db->connection()->posts." WHERE post_type='aish_message'");$audit=(int)$db->value('SELECT COUNT(*) FROM '.$db->table('workflow_events'));$old=$GLOBALS['wpdb']->suppress_errors(true);add_filter('query',$inject,PHP_INT_MAX);try{p13_reject(fn()=>$sponsors->setEnabled(!$s['enabled'],$s['revision']),'Sponsor config audit failure rejects commit');p13_reject(fn()=>$enterprise->saveConfig(['enabled'=>false,'translations'=>$e['translations']],$e['revision']),'Enterprise config audit failure rejects commit');p13_reject(fn()=>$enterprise->receive($input,'en_US',hash('sha256',$run.':rollback')),'Private Inbox audit failure rejects commit');p13_reject(fn()=>$bundles->save(['state'=>'paused','collection_ids'=>$b['collection_ids'],'reason'=>'Rollback-only test'],$b['revision'],true),'Bundle config audit failure rejects commit');}finally{remove_filter('query',$inject,PHP_INT_MAX);$GLOBALS['wpdb']->suppress_errors($old);}p13_assert($sponsors->snapshot()===$s&&Enterprise::snapshot()===$e&&$bundles->configuration()===$b,'All configuration JSON/revisions rolled back');p13_assert((int)$db->value('SELECT COUNT(*) FROM '.$db->connection()->posts." WHERE post_type='aish_message'")===$count,'No orphan private inquiry post');p13_assert((int)$db->value('SELECT COUNT(*) FROM '.$db->table('workflow_events'))===$audit,'No partial audit entries');});
wp_set_current_user($admin);$enterprise->saveConfig(['enabled'=>$initial['enabled'],'translations'=>$initial['translations']],Enterprise::snapshot()['revision']);
